196→	if err != nil && !errors.Is(err, os.ErrNotExist) {
197→		return fmt.Errorf("read %s: %w", excludePath, err)
198→	}
199→
200→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
201→	for _, line := range strings.Split(normalized, "\n") {
202→		if strings.TrimSpace(line) == entry {
203→			return nil
204→		}
205→	}
206→
207→	var b strings.Builder
208→	if len(data) > 0 {
209→		b.Write(data)
210→		if data[len(data)-1] != '\n' {
211→			b.WriteByte('\n')
212→		}
213→	}
214→	b.WriteString(entry)
215→	b.WriteByte('\n')
