522→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
523→// branch for the given checkpoint ID and session index, then returns it.
524→// This handles the race where the checkpoint branch advances before session
525→// metadata is fully committed.
526→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
527→	t.Helper()
528→
529→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
530→	blob := "entire/checkpoints/v1:" + path
531→
532→	deadline := time.Now().Add(timeout)
533→	for time.Now().Before(deadline) {
534→		raw := gitOutputSafe(dir, "show", blob)
535→		if raw != "" {
536→			var meta SessionMetadata
537→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
538→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
539→			}
540→			return meta
541→		}
542→		time.Sleep(500 * time.Millisecond)
543→	}
544→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
545→	return SessionMetadata{}
546→}
