112→// AssertNoShadowBranches asserts that no shadow branches (entire/*) remain,
113→// excluding entire/checkpoints/*. Shadow branches should be cleaned up after
114→// commits condense session data to the metadata branch.
115→//
116→// Polls briefly because shadow branch deletion in the post-commit hook runs
117→// immediately after the checkpoint branch is written but is not atomic with it.
118→func AssertNoShadowBranches(t *testing.T, dir string) {
119→	t.Helper()
120→	deadline := time.Now().Add(5 * time.Second)
121→	for {
122→		shadow := shadowBranches(t, dir)
123→		if len(shadow) == 0 {
124→			return
125→		}
126→		if time.Now().After(deadline) {
127→			assert.Empty(t, shadow,
128→				"shadow branches should be cleaned up after commit, found: %v", shadow)
129→			return
130→		}
131→		time.Sleep(200 * time.Millisecond)
132→	}
133→}
