236→// WaitForCheckpointAdvanceFrom polls until the checkpoint branch advances from
237→// the given ref, or fails the test after timeout. Use this when waiting for a
238→// second (or subsequent) checkpoint after recording the branch position.
239→func WaitForCheckpointAdvanceFrom(t *testing.T, dir string, fromRef string, timeout time.Duration) {
240→	t.Helper()
241→	deadline := time.Now().Add(timeout)
242→	for time.Now().Before(deadline) {
243→		after := GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1")
244→		if after != fromRef {
245→			return
246→		}
247→		time.Sleep(200 * time.Millisecond)
248→	}
249→	t.Fatalf("checkpoint branch did not advance from %s within %s", fromRef[:8], timeout)
250→}
