252→// WaitForSessionIdle polls the session state files in .git/entire-sessions/
253→// until no session has phase "active", or fails the test after timeout.
254→// This handles the race where an agent's prompt pattern appears in the TUI
255→// before the turn-end hook has completed (transitioning ACTIVE → IDLE).
256→func WaitForSessionIdle(t *testing.T, dir string, timeout time.Duration) {
257→	t.Helper()
258→	stateDir := filepath.Join(dir, ".git", "entire-sessions")
259→	deadline := time.Now().Add(timeout)
260→	for time.Now().Before(deadline) {
261→		entries, err := os.ReadDir(stateDir)
262→		if err != nil {
263→			// Directory may not exist yet; keep polling
264→			time.Sleep(200 * time.Millisecond)
265→			continue
266→		}
267→		anyActive := false
268→		for _, entry := range entries {
269→			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") || strings.HasSuffix(entry.Name(), ".tmp") {
270→				continue
271→			}
272→			data, err := os.ReadFile(filepath.Join(stateDir, entry.Name()))
273→			if err != nil {
274→				continue
275→			}
276→			var state struct {
277→				Phase string `json:"phase"`
278→			}
279→			if err := json.Unmarshal(data, &state); err != nil {
280→				continue
281→			}
282→			if state.Phase == "active" {
283→				anyActive = true
284→				break
285→			}
286→		}
287→		if !anyActive {
288→			return
289→		}
290→		time.Sleep(200 * time.Millisecond)
291→	}
292→	t.Fatalf("session(s) did not transition to idle within %s", timeout)
293→}
