332→// ValidateCheckpointDeep performs comprehensive validation of checkpoint metadata
333→// on the checkpoint branch, including transcript JSONL validity, content hash
334→// verification, and prompt content checking.
335→func ValidateCheckpointDeep(t *testing.T, dir string, v DeepCheckpointValidation) {
336→	t.Helper()
337→
338→	// Basic metadata validation
339→	AssertCheckpointExists(t, dir, v.CheckpointID)
340→	AssertCheckpointMetadataComplete(t, dir, v.CheckpointID)
341→
342→	if v.Strategy != "" {
343→		meta := ReadCheckpointMetadata(t, dir, v.CheckpointID)
344→		assert.Equal(t, v.Strategy, meta.Strategy,
345→			"checkpoint %s: strategy mismatch", v.CheckpointID)
346→	}
347→
348→	if len(v.FilesTouched) > 0 {
349→		AssertCheckpointFilesTouched(t, dir, v.CheckpointID, v.FilesTouched)
350→	}
351→
352→	path := CheckpointPath(v.CheckpointID)
353→
354→	// Validate session metadata exists and has checkpoint_id
355→	sessionBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/metadata.json", path)
356→	sessionRaw := gitOutputSafe(dir, "show", sessionBlob)
357→	if assert.NotEmpty(t, sessionRaw, "session metadata should exist at %s", sessionBlob) {
358→		var sessionMeta map[string]any
359→		if assert.NoError(t, json.Unmarshal([]byte(sessionRaw), &sessionMeta)) {
360→			assert.Equal(t, v.CheckpointID, sessionMeta["checkpoint_id"],
361→				"session metadata checkpoint_id should match")
362→			assert.NotEmpty(t, sessionMeta["created_at"], "session metadata should have created_at")
363→		}
364→	}
365→
366→	// Validate transcript is valid JSONL
367→	transcriptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/full.jsonl", path)
368→	transcriptRaw := gitOutputSafe(dir, "show", transcriptBlob)
369→	if assert.NotEmpty(t, transcriptRaw, "transcript should exist at %s", transcriptBlob) {
370→		lines := strings.Split(transcriptRaw, "\n")
371→		nonEmpty := 0
372→		for _, line := range lines {
373→			if strings.TrimSpace(line) != "" {
374→				nonEmpty++
375→			}
376→		}
377→		assert.Positive(t, nonEmpty, "transcript should have at least one line")
378→
379→		for _, expected := range v.ExpectedTranscriptContent {
380→			assert.Contains(t, transcriptRaw, expected,
381→				"transcript should contain %q", expected)
382→		}
383→
384→		// Validate content hash
385→		hashBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/content_hash.txt", path)
386→		hashRaw := gitOutputSafe(dir, "show", hashBlob)
387→		if hashRaw != "" {
388→			hash := sha256.Sum256([]byte(transcriptRaw))
389→			expectedHash := "sha256:" + hex.EncodeToString(hash[:])
390→			assert.Equal(t, expectedHash, strings.TrimSpace(hashRaw),
391→				"content hash should match transcript SHA-256")
392→		}
393→	}
394→
395→	// Validate prompt.txt if expected prompts specified
396→	if len(v.ExpectedPrompts) > 0 {
397→		promptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/prompt.txt", path)
398→		promptRaw := gitOutputSafe(dir, "show", promptBlob)
399→		for _, expected := range v.ExpectedPrompts {
400→			assert.Contains(t, promptRaw, expected,
401→				"prompt.txt should contain %q", expected)
402→		}
403→	}
404→}
