 14→
 15→// cleanConfigDir creates an isolated temp directory for CLAUDE_CONFIG_DIR so
 16→// that E2E test runs don't inherit any user settings (CLAUDE.md, skills,
 17→// projects, plugins, etc.).
 18→//
 19→// On CI, it symlinks .claude.json (which Bootstrap() wrote with the API key
 20→// and hasCompletedOnboarding). Locally, it writes a minimal .claude.json to
 21→// skip the onboarding flow — Keychain-based auth works without any other files.
 22→func cleanConfigDir() (string, error) {
 23→	dst, err := os.MkdirTemp("", "claude-config-*")
 24→	if err != nil {
 25→		return "", err
 26→	}
 27→
 28→	if os.Getenv("CI") != "" {
 29→		if home, err := os.UserHomeDir(); err == nil {
 30→			src := filepath.Join(home, ".claude", ".claude.json")
 31→			if _, err := os.Stat(src); err == nil {
 32→				_ = os.Symlink(src, filepath.Join(dst, ".claude.json"))
 33→			}
 34→		}
 35→	} else {
 36→		_ = os.WriteFile(filepath.Join(dst, ".claude.json"),
 37→			[]byte(`{"hasCompletedOnboarding":true}`), 0o644)
 38→	}
 39→
 40→	return dst, nil
 41→}
 42→
 43→// cleanEnv returns os.Environ() with CLAUDECODE removed so that
 44→// Claude Code doesn't refuse to start inside this test runner.
 45→func cleanEnv() []string {
 46→	var env []string
 47→	for _, e := range os.Environ() {
 48→		if !strings.HasPrefix(e, "CLAUDECODE=") {
 49→			env = append(env, e)
 50→		}
 51→	}
 52→	return env
 53→}
 54→
 55→func init() {
 56→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "claude-code" {
 57→		return
 58→	}
 59→	Register(&Claude{})
 60→}
 61→
 62→type Claude struct{}
 63→
 64→func (c *Claude) Name() string               { return "claude-code" }
 65→func (c *Claude) Binary() string             { return "claude" }
 66→func (c *Claude) EntireAgent() string        { return "claude-code" }
 67→func (c *Claude) PromptPattern() string      { return `❯` }
 68→func (c *Claude) TimeoutMultiplier() float64 { return 1.0 }
 69→
 70→func (c *Claude) IsTransientError(out Output, _ error) bool {
 71→	transientPatterns := []string{
 72→		"overloaded",
 73→		"rate limit",
 74→		"529",
 75→		"503",
 76→		"ECONNRESET",
 77→		"ETIMEDOUT",
 78→	}
 79→	for _, p := range transientPatterns {
 80→		if strings.Contains(out.Stderr, p) {
 81→			return true
 82→		}
 83→	}
 84→	return false
 85→}
 86→
 87→func (c *Claude) Bootstrap() error {
 88→	// On CI, write a config file so Claude Code uses the API key from the
 89→	// environment instead of trying OAuth/Keychain.
 90→	if os.Getenv("CI") == "" {
 91→		return nil
 92→	}
 93→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
 94→	if apiKey == "" {
 95→		return nil
 96→	}
 97→	home, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return fmt.Errorf("get home dir: %w", err)
100→	}
101→	dir := filepath.Join(home, ".claude")
102→	if err := os.MkdirAll(dir, 0o755); err != nil {
103→		return fmt.Errorf("mkdir %s: %w", dir, err)
104→	}
105→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
106→	path := filepath.Join(dir, ".claude.json")
107→	return os.WriteFile(path, []byte(config), 0o644)
108→}
109→
110→func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
111→	cfg := &runConfig{Model: "haiku"}
112→	for _, o := range opts {
113→		o(cfg)
114→	}
115→
116→	configDir, err := cleanConfigDir()
117→	if err != nil {
118→		return Output{}, fmt.Errorf("create clean config dir: %w", err)
119→	}
120→	defer func() { _ = os.RemoveAll(configDir) }()
121→
122→	env := append(cleanEnv(),
123→		"ACCESSIBLE=1",
124→		"ENTIRE_TEST_TTY=0",
125→
126→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
127→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
128→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
129→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
130→		// itself, clone its plugins, etc.
131→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
132→		"CLAUDE_CONFIG_DIR="+configDir,
133→	)
134→
135→	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
136→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
137→	cmd := exec.CommandContext(ctx, c.Binary(), args...)
138→	cmd.Dir = dir
139→	cmd.Stdin = nil
140→	cmd.Env = env
141→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
142→	cmd.Cancel = func() error {
143→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
144→	}
145→	cmd.WaitDelay = 5 * time.Second
146→
147→	var stdout, stderr strings.Builder
148→	cmd.Stdout = &stdout
149→	cmd.Stderr = &stderr
150→
151→	err = cmd.Run()
152→	exitCode := 0
153→	if err != nil {
154→		exitErr := &exec.ExitError{}
155→		if errors.As(err, &exitErr) {
156→			exitCode = exitErr.ExitCode()
157→		} else {
158→			exitCode = -1
159→		}
160→	}
161→
162→	return Output{
163→		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
164→		Stdout:   stdout.String(),
165→		Stderr:   stderr.String(),
166→		ExitCode: exitCode,
167→	}, err
168→}
169→
170→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
171→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
172→
173→	configDir, err := cleanConfigDir()
174→	if err != nil {
175→		return nil, fmt.Errorf("create clean config dir: %w", err)
176→	}
177→
178→	envArgs := []string{
179→		"ACCESSIBLE=1",
180→		"ENTIRE_TEST_TTY=0",
181→
182→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
183→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
184→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
185→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
186→		// itself, clone its plugins, etc.
187→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
188→		"CLAUDE_CONFIG_DIR=" + configDir,
189→	}
190→
191→	args := append([]string{"env"}, envArgs...)
192→	args = append(args, c.Binary(), "--dangerously-skip-permissions")
193→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, args[0], args[1:]...)
194→	if err != nil {
195→		_ = os.RemoveAll(configDir)
196→		return nil, err
197→	}
198→	s.OnClose(func() { _ = os.RemoveAll(configDir) })
199→
200→	// Dismiss startup dialogs until we reach the input prompt.
201→	for range 5 {
202→		content, err := s.WaitFor(`❯`, 15*time.Second)
203→		if err != nil {
204→			_ = s.Close()
205→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
206→		}
207→		if !strings.Contains(content, "Enter to confirm") {
208→			break
209→		}
210→		// The bypass permissions dialog defaults to "No, exit" —
211→		// arrow down to "Yes, I accept" before confirming.
212→		if strings.Contains(content, "Yes, I accept") {
213→			_ = s.SendKeys("Down")
214→			time.Sleep(200 * time.Millisecond)
215→		}
216→		_ = s.SendKeys("Enter")
217→		time.Sleep(500 * time.Millisecond)
218→	}
219→	s.stableAtSend = ""
220→
221→	return s, nil
222→}
