 55→func (g *Gemini) Bootstrap() error {
 56→	// Pre-configure auth so gemini doesn't show the onboarding dialog.
 57→	home, err := os.UserHomeDir()
 58→	if err != nil {
 59→		return fmt.Errorf("get home dir: %w", err)
 60→	}
 61→	dir := filepath.Join(home, ".gemini")
 62→	if err := os.MkdirAll(dir, 0o755); err != nil {
 63→		return fmt.Errorf("mkdir %s: %w", dir, err)
 64→	}
