 69→func (g *Gemini) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 70→	cfg := &runConfig{Model: geminiDefaultModel}
 71→	for _, o := range opts {
 72→		o(cfg)
 73→	}
 74→
 75→	// Per-prompt timeout so a slow response gets killed early enough to
 76→	// retry within the test's overall budget.
 77→	timeout := 60 * time.Second
 78→	if cfg.PromptTimeout > 0 {
 79→		timeout = cfg.PromptTimeout
 80→	}
 81→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
 82→	defer cancel()
 83→
 84→	args := []string{"-p", prompt, "--model", cfg.Model, "-y"}
 85→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "-y"}
 86→	cmd := exec.CommandContext(promptCtx, g.Binary(), args...)
 87→	cmd.Dir = dir
 88→	cmd.Stdin = nil
 89→	cmd.Env = append(os.Environ(), "ACCESSIBLE=1", "ENTIRE_TEST_TTY=0")
 90→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 91→	cmd.Cancel = func() error {
 92→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 93→	}
 94→	cmd.WaitDelay = 5 * time.Second
 95→
 96→	var stdout, stderr strings.Builder
 97→	cmd.Stdout = &stdout
 98→	cmd.Stderr = &stderr
 99→
100→	err := cmd.Run()
101→	exitCode := 0
102→	if err != nil {
103→		exitErr := &exec.ExitError{}
104→		if errors.As(err, &exitErr) {
105→			exitCode = exitErr.ExitCode()
106→		} else {
107→			exitCode = -1
108→		}
109→		// Wrap the prompt-level deadline so IsTransientError can detect it.
110→		// cmd.Run() returns "signal: killed", not the context error.
111→		if promptCtx.Err() == context.DeadlineExceeded {
112→			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
113→		}
114→	}
115→
116→	return Output{
117→		Command:  g.Binary() + " " + strings.Join(displayArgs, " "),
118→		Stdout:   stdout.String(),
119→		Stderr:   stderr.String(),
120→		ExitCode: exitCode,
121→	}, err
122→}
