 57→// droidSettings represents the ~/.factory/settings.json structure used for
 58→// BYOK (Bring Your Own Key) configuration and session defaults.
 59→type droidSettings struct {
 60→	CustomModels           []droidCustomModel    `json:"customModels,omitempty"`
 61→	SessionDefaultSettings *droidSessionDefaults `json:"sessionDefaultSettings,omitempty"`
 62→}
 63→
 64→type droidCustomModel struct {
 65→	DisplayName    string `json:"displayName"`
 66→	Model          string `json:"model"`
 67→	BaseURL        string `json:"baseUrl"`
 68→	APIKey         string `json:"apiKey"`
 69→	Provider       string `json:"provider"`
 70→	MaxOutputToken int    `json:"maxOutputTokens"`
 71→}
