196→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
197→	const maxAttempts = 2
198→
199→	var s *TmuxSession
200→	var lastErr error
201→	for attempt := range maxAttempts {
202→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
203→		var err error
204→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
205→		if err != nil {
206→			return nil, err
207→		}
208→
209→		// Resize so droid's full-screen TUI has room to render the prompt area.
210→		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
211→		_ = exec.Command("tmux", "resize-window", "-t", name, "-x", "200", "-y", "50").Run()
212→
213→		// Wait for the interactive prompt indicator.
214→		if _, err := s.WaitFor(d.PromptPattern(), 60*time.Second); err != nil {
215→			_ = s.Close()
216→			if attempt < maxAttempts-1 {
217→				lastErr = err
218→				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed: %s\n", attempt+1, maxAttempts, err)
219→				continue
220→			}
221→			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", maxAttempts, err)
222→		}
223→		s.stableAtSend = ""
224→		return s, nil
225→	}
226→	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", maxAttempts, lastErr)
227→}
